-- READ-ONLY verification for 2027-01-17_customer_consent_events.sql. Run AFTER applying it. Every row should say ok = true.
select 'ledger table exists and is ours' as check_name, coalesce(obj_description(to_regclass('public.customer_consent_events'), 'pg_class'), '') = 'managed by 2027-01-17_customer_consent_events.sql' as ok;
select 'row-level security is on, no policy' as check_name, (select relrowsecurity from pg_class where oid = 'public.customer_consent_events'::regclass) and not exists (select 1 from pg_policy where polrelid = 'public.customer_consent_events'::regclass) as ok;
select 'no API role can reach the ledger' as check_name, not (has_any_column_privilege('anon', 'public.customer_consent_events', 'select') or has_any_column_privilege('authenticated', 'public.customer_consent_events', 'select') or has_any_column_privilege('authenticated', 'public.customer_consent_events', 'insert') or has_any_column_privilege('anon', 'public.customer_consent_events', 'insert')) as ok;
select 'service role can read and append, not edit or delete' as check_name, has_table_privilege('service_role', 'public.customer_consent_events', 'select') and has_table_privilege('service_role', 'public.customer_consent_events', 'insert') and not has_table_privilege('service_role', 'public.customer_consent_events', 'update') and not has_table_privilege('service_role', 'public.customer_consent_events', 'delete') as ok;
select 'writer is callable by the service role only' as check_name, has_function_privilege('service_role', 'public.customer_consent_set(uuid, uuid, text, text, text)', 'execute') and not has_function_privilege('anon', 'public.customer_consent_set(uuid, uuid, text, text, text)', 'execute') and not has_function_privilege('authenticated', 'public.customer_consent_set(uuid, uuid, text, text, text)', 'execute') as ok;
select 'append-only triggers are present (update/delete and truncate)' as check_name, (select count(*) from pg_trigger where tgrelid = 'public.customer_consent_events'::regclass and tgname in ('customer_consent_events_immutable_trg', 'customer_consent_events_no_truncate_trg') and not tgisinternal) = 2 as ok;
-- informational: legacy consent that exists without a ledger row (expected: all of it before the first decision is made in the app)
select count(*) as legacy_consenting_connections_without_ledger_row from public.customer_connections cc where cc.marketing_consent and not exists (select 1 from public.customer_consent_events e where e.customer_id = cc.customer_id and e.profile_id = cc.profile_id and e.channel = 'email');
